import React, { useState } from 'react';
import { Sparkles, CheckCircle2, Info, X } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    question: "Do you offer outdoor seating?",
    answer: "Yes, we have a charming outdoor terrace with retractable heaters for cooler evenings. Reservations are recommended.",
    isOpen: false,
  },
  {
    id: 2,
    question: "What types of vegetarian dishes do you have?",
    answer: "Our seasonal menu features a variety of plant-based options, including heirloom salads, wild mushroom risotto, and seasonal vegetable gnocchi.",
    isOpen: false,
  },
  {
    id: 3,
    question: "Can I bring my own wine?",
    answer: "Absolutely! We welcome BYOB guests. Please inform us of your selections upon reservation.",
    isOpen: false,
  },
  {
    id: 4,
    question: "Do you offer delivery or takeout?",
    answer: "Currently, we do not offer delivery or takeout. However, you can enjoy our cuisine at our intimate dining room or on our beautiful outdoor terrace.",
    isOpen: false,
  },
  {
    id: 5,
    question: "What are your business hours?",
    answer: "We are open daily from 11:00 AM to 10:00 PM. Reservations are required for groups of 4 or more.",
    isOpen: false,
  },
];

export default function Faq() {
  const [activeId, setActiveId] = useState(null);

  const toggleAccordion = (id) => {
    if (activeId === id) {
      setActiveId(null);
    } else {
      setActiveId(id);
    }
  };

  const isExpanded = (id) => activeId === id;

  return (
    <div className="w-full max-w-6xl mx-auto p-4 sm:p-6 bg-white/5 rounded-2xl border border-white/10 shadow-2xl backdrop-blur-xl text-slate-900">
      <div className="flex flex-col sm:flex-row justify-between items-center mb-8">
        <div>
          <h2 className="text-2xl font-bold tracking-tight text-slate-950 mb-2">
            Frequently Asked Questions
          </h2>
          <p className="text-sm text-slate-500 mb-6">
            Get the answers to your most common queries about dining at Casa Verde.
          </p>
        </div>
        <div className="flex gap-3">
          <button className="flex gap-1.5 p-2 rounded-xl bg-white/5 border border-white/10 text-slate-400 hover:text-white hover:bg-white/10 transition-colors">
            <Sparkles className="w-4 h-4" />
            <span>Filter</span>
          </button>
          <button className="flex gap-1.5 p-2 rounded-xl bg-white/5 border border-white/10 text-slate-400 hover:text-white hover:bg-white/10 transition-colors">
            <Info className="w-4 h-4" />
            <span>Help</span>
          </button>
        </div>
      </div>

      <div className="space-y-4">
        {faqItems.map((item) => {
          const Icon = isExpanded(item.id) ? CheckCircle2 : Info;
          return (
            <div
              key={item.id}
              className="group relative flex flex-col sm:flex-row items-start justify-between p-4 hover:bg-white/10 transition-all duration-300"
            >
              <div className="flex items-start sm:items-center gap-3">
                <div className="flex flex-col sm:flex-row sm:gap-1.5">
                  <div className="w-3 h-3 bg-amber-500/20 rounded-full group-hover:bg-amber-500/50 transition-colors" />
                  {item.id === activeId && (
                    <span className="flex items-center gap-1 font-medium text-slate-200">
                      <span className="bg-white/5 p-1 rounded-full text-xs font-semibold">{item.id}</span>
                      <span>{item.question}</span>
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-1.5 text-slate-500">
                  <span className="bg-white/5 p-1 rounded-full text-xs font-semibold">{item.id}</span>
                  <Icon className="w-5 h-5 text-amber-400" />
                </div>
              </div>
              <div className="flex items-center justify-end sm:justify-start gap-2">
                <div className="flex items-center gap-1.5 self-start text-slate-400">
                  <span className="bg-white/5 p-1 rounded-full text-xs font-semibold">{item.id}</span>
                  <Info className="w-5 h-5" />
                </div>
                <button
                  onClick={() => toggleAccordion(item.id)}
                  className="flex items-center justify-end text-slate-400 hover:text-white transition-colors"
                >
                  <span className="bg-white/5 p-1 rounded-full text-xs font-semibold">{item.id}</span>
                  <X className="w-5 h-5" />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default function Hero() {
  return (
    <section id="hero" className="py-20">
      <div className="max-w-4xl mx-auto px-6 text-slate-700">
        <h2 className="text-3xl font-bold mb-4">Hero</h2>
      </div>
    </section>
  );
}

