import React, { useState } from 'react';
import { MapPin, Clock, UtensilsCrossed, Calendar, X, CheckCircle2, Sparkles, Sparkle, Check, ArrowRight } from 'lucide-react';

const initialDetails = {
  name: 'Davide Rossi',
  phone: '+1 555-1234',
  email: 'davide@verde.com',
  guests: 4,
  date: '2024-03-22',
  time: '18:00',
};

export default function Reservations() {
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [formData, setFormData] = useState(initialDetails);
  const [errors, setErrors] = useState({});

  const validate = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = 'Please enter your full name.';
    if (!formData.phone.trim()) newErrors.phone = 'Please provide a valid phone number.';
    if (!formData.email.trim() || !formData.email.includes('@')) newErrors.email = 'Please enter a valid email address.';
    if (!formData.date || !formData.time) newErrors.date = 'Please select a date and time.';
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSuccess(true);
      setFormData(initialDetails); // Reset form on success
    }, 1500);
  };

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 sm:p-12">
      <div className="w-full max-w-md relative overflow-hidden rounded-2xl bg-white/5 border border-white/10 p-8 shadow-2xl transition-all duration-300 hover:shadow-xl">

        {/* Header with background gradient */}
        <div className="absolute top-0 left-0 right-0 h-32 bg-gradient-to-b from-indigo-600 via-purple-600 to-pink-600 opacity-50 pointer-events-none" />

        {/* Decorative top border */}
        <div className="relative -mt-px h-1.5 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500" />

        {/* Header row */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-8 px-4 sm:px-0">
          <div>
            <div className="flex items-center gap-2">
              <MapPin className="w-5 h-5 text-amber-400" />
              <h2 className="text-xl font-bold text-slate-100 tracking-tight">Reserve a Table</h2>
            </div>
            <p className="text-sm text-slate-400 mt-1">Easily book your perfect table for a memorable dining experience.</p>
          </div>
          {/* Decorative accent box */}
          <div className="w-full sm:w-1/2 h-1 bg-amber-500 rounded-full" />
        </div>

        {/* Main form */}
        <form onSubmit={handleSubmit} className="space-y-4 w-full max-w-md">
          {isSuccess ? (
            <div className="p-6 rounded-2xl bg-emerald-500/10 border border-emerald-500/20 text-emerald-400 shadow-inner animate-fade-in">
              <CheckCircle2 className="w-10 h-10 mx-auto text-emerald-300 mb-4" />
              <h3 className="text-sm font-medium text-slate-200">Reservation Confirmed!</h3>
              <p className="text-xs text-slate-400">We'll send a confirmation email shortly.</p>
            </div>
          ) : (
            <>
              {/* Name & Contact Fields */}
              <div className="space-y-2">
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                  <div className="col-span-2 sm:col-span-1">
                    <label htmlFor="name" className="block text-sm font-medium text-slate-300">Full Name</label>
                    <input
                      id="name"
                      name="name"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      placeholder="Davide Rossi"
                      required
                    />
                    {errors.name && <p className="text-xs text-rose-500">{errors.name}</p>}
                  </div>
                  <div className="col-span-2 sm:col-span-3">
                    <label htmlFor="email" className="block text-sm font-medium text-slate-300">Email Address</label>
                    <input
                      id="email"
                      name="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      placeholder="davide@verde.com"
                      required
                    />
                    {errors.email && <p className="text-xs text-rose-500">{errors.email}</p>}
                  </div>
                  <div className="col-span-2 sm:col-span-1">
                    <label htmlFor="phone" className="block text-sm font-medium text-slate-300">Phone Number</label>
                    <input
                      id="phone"
                      name="phone"
                      value={formData.phone}
                      onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      placeholder="+1 (555) 1234"
                      required
                    />
                    {errors.phone && <p className="text-xs text-rose-500">{errors.phone}</p>}
                  </div>
                </div>
              </div>

              {/* Date & Time Picker */}
              <div className="grid grid-cols-2 gap-4 sm:grid-cols-1">
                <div className="relative z-10">
                  <label htmlFor="date" className="block text-sm font-medium text-slate-300">Date</label>
                  <div className="relative mt-2">
                    <input
                      id="date"
                      name="date"
                      type="date"
                      value={formData.date}
                      onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      required
                    />
                    {errors.date && <p className="text-xs text-rose-500">{errors.date}</p>}
                  </div>
                </div>
                <div className="relative z-10">
                  <label htmlFor="time" className="block text-sm font-medium text-slate-300">Time</label>
                  <div className="relative mt-2">
                    <input
                      id="time"
                      name="time"
                      type="time"
                      value={formData.time}
                      onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      required
                    />
                    {errors.time && <p className="text-xs text-rose-500">{errors.time}</p>}
                  </div>
                </div>
              </div>

              {/* Guests & Table Type */}
              <div className="sm:flex sm:items-center sm:gap-4">
                <div className="w-full sm:w-auto">
                  <label htmlFor="guests" className="block text-sm font-medium text-slate-300">Party Size</label>
                  <div className="relative mt-2 sm:mt-0">
                    <select
                      id="guests"
                      name="guests"
                      value={formData.guests}
                      onChange={(e) => setFormData({ ...formData, guests: e.target.value })}
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                    >
                      <option value={2}>2 Guests</option>
                      <option value={4}>4 Guests</option>
                      <option value={6}>6 Guests</option>
                      <option value={8}>8 Guests</option>
                    </select>
                  </div>
                </div>
                {/* Decorative divider */}
                <div className="h-8 w-px bg-white/10 mx-4" />
                <div className="w-full sm:w-auto">
                  <label htmlFor="table-type" className="block text-sm font-medium text-slate-300">Table Type</label>
                  <div className="relative mt-2 sm:mt-0">
                    <select
                      id="table-type"
                      name="table-type"
                      className="w-full bg-white/5 border border-white/10 text-slate-300 rounded-md py-2 px-3 placeholder:text-slate-500 focus:ring-2 focus:ring-amber-500 outline-none transition-all"
                      disabled
                    >
                      <option defaultValue="default" disabled selected>Select Your Table</option>
                      <option value="outdoor">Outdoor Seating</option>
                      <option value="private">Private Room</option>
                      <option value="bar">Bar Top</option>
                    </select>
                  </div>
                </div>
              </div>

              {/* Submit button with loading state */}
              <button
                type="submit"
                disabled={isSubmitting}
                className="w-full rounded-xl bg-amber-600 hover:bg-amber-700 text-white font-semibold py-3 transition-all duration-200"
              >
                {isSubmitting ? (
                  <div className="flex items-center gap-2">
                    <Sparkle className="w-4 h-4 animate-spin-slow text-white" /> <span>Sending...</span>
                  </div>
                ) : (
                  <span>Reserve Table</span>
                )}
              </button>
            </>
          )}
        </form>

        {/* Decorative bottom border */}
        <div className="absolute bottom-0 left-0 right-0 h-1 bg-slate-900" />
      </div>
    </div>
  );
}
